import React from 'react';
import { CartItem } from './types';
import './OrderSummary.css';

interface OrderSummaryProps {
  items: CartItem[];
}

const formatPrice = (value: number): string => `$${value.toFixed(2)}`;

export function OrderSummary({ items }: OrderSummaryProps) {
  const subtotal = items.reduce((sum, item) => sum + item.unitPrice * item.quantity, 0);
  const shipping = items.length > 0 ? 5.99 : 0;
  const total = subtotal + shipping;

  if (items.length === 0) {
    return (
      <div className="order-summary order-summary--empty">
        <p>Your cart is empty.</p>
      </div>
    );
  }

  return (
    <div className="order-summary">
      <h2 className="order-summary__title">Your order</h2>
      <ul className="order-summary__list">
        {items.map((item) => (
          <li key={item.id} className="order-summary__item">
            <div className="order-summary__thumb">
              {item.imageUrl ? (
                <img src={item.imageUrl} alt={item.name} />
              ) : (
                <div className="order-summary__thumb-placeholder" aria-hidden="true" />
              )}
              <span className="order-summary__qty-badge">{item.quantity}</span>
            </div>
            <div className="order-summary__details">
              <span className="order-summary__name">{item.name}</span>
              <span className="order-summary__unit-price">{formatPrice(item.unitPrice)} each</span>
            </div>
            <span className="order-summary__line-total">
              {formatPrice(item.unitPrice * item.quantity)}
            </span>
          </li>
        ))}
      </ul>

      <div className="order-summary__totals">
        <div className="order-summary__row">
          <span>Subtotal</span>
          <span>{formatPrice(subtotal)}</span>
        </div>
        <div className="order-summary__row">
          <span>Shipping</span>
          <span>{formatPrice(shipping)}</span>
        </div>
        <div className="order-summary__row order-summary__row--total">
          <span>Total</span>
          <span>{formatPrice(total)}</span>
        </div>
      </div>
    </div>
  );
}
```

