import React from 'react';
import { Address, AddressErrors } from './types';
import './AddressForm.css';

interface AddressFormProps {
  address: Address;
  errors: AddressErrors;
  onChange: (field: keyof Address, value: string) => void;
}

interface FieldConfig {
  name: keyof Address;
  label: string;
  required: boolean;
  autoComplete: string;
  span?: 'full' | 'half';
}

const FIELDS: FieldConfig[] = [
  { name: 'fullName', label: 'Full name', required: true, autoComplete: 'name', span: 'full' },
  { name: 'line1', label: 'Address line 1', required: true, autoComplete: 'address-line1', span: 'full' },
  { name: 'line2', label: 'Address line 2 (optional)', required: false, autoComplete: 'address-line2', span: 'full' },
  { name: 'city', label: 'City', required: true, autoComplete: 'address-level2', span: 'half' },
  { name: 'postalCode', label: 'Postal code', required: true, autoComplete: 'postal-code', span: 'half' },
  { name: 'country', label: 'Country', required: true, autoComplete: 'country-name', span: 'half' },
  { name: 'phone', label: 'Phone', required: true, autoComplete: 'tel', span: 'half' },
];

export function AddressForm({ address, errors, onChange }: AddressFormProps) {
  return (
    <div className="address-form">
      <h2 className="address-form__title">Delivery address</h2>
      <div className="address-form__grid">
        {FIELDS.map((field) => {
          const inputId = `address-${field.name}`;
          const errorId = `${inputId}-error`;
          const error = errors[field.name];

          return (
            <div
              key={field.name}
              className={`address-form__field address-form__field--${field.span ?? 'full'}`}
            >
              <label htmlFor={inputId} className="address-form__label">
                {field.label}
                {field.required && <span aria-hidden="true"> *</span>}
              </label>
              <input
                id={inputId}
                name={field.name}
                className={`address-form__input ${error ? 'address-form__input--error' : ''}`}
                value={address[field.name] ?? ''}
                autoComplete={field.autoComplete}
                aria-required={field.required}
                aria-invalid={Boolean(error)}
                aria-describedby={error ? errorId : undefined}
                onChange={(e) => onChange(field.name, e.target.value)}
              />
              {error && (
                <span id={errorId} className="address-form__error" role="alert">
                  {error}
                </span>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}
