**CheckoutPage.tsx**
```tsx
import React, { useState } from 'react';
import { Address, AddressErrors, CartItem } from './types';
import { OrderSummary } from './OrderSummary';
import { AddressForm } from './AddressForm';
import './CheckoutPage.css';

interface CheckoutPageProps {
  cartItems: CartItem[];
  onBackToCart: () => void;
  onPay: (address: Address) => void;
}

const EMPTY_ADDRESS: Address = {
  fullName: '',
  line1: '',
  line2: '',
  city: '',
  postalCode: '',
  country: '',
  phone: '',
};

const REQUIRED_FIELDS: (keyof Address)[] = ['fullName', 'line1', 'city', 'postalCode', 'country', 'phone'];

function validateAddress(address: Address): AddressErrors {
  const errors: AddressErrors = {};
  for (const field of REQUIRED_FIELDS) {
    if (!address[field]?.trim()) {
      errors[field] = 'This field is required';
    }
  }
  return errors;
}

export default function CheckoutPage({ cartItems, onBackToCart, onPay }: CheckoutPageProps) {
  const [address, setAddress] = useState<Address>(EMPTY_ADDRESS);
  const [errors, setErrors] = useState<AddressErrors>({});
  const [isPaying, setIsPaying] = useState(false);

  const handleFieldChange = (field: keyof Address, value: string) => {
    setAddress((prev) => ({ ...prev, [field]: value }));
    setErrors((prev) => {
      if (!prev[field]) return prev;
      const next = { ...prev };
      delete next[field];
      return next;
    });
  };

  const handlePay = async () => {
    const validationErrors = validateAddress(address);
    setErrors(validationErrors);

    if (Object.keys(validationErrors).length > 0 || cartItems.length === 0) {
      return;
    }

    setIsPaying(true);
    try {
      await onPay(address);
    } finally {
      setIsPaying(false);
    }
  };

  const canPay = cartItems.length > 0 && !isPaying;

  return (
    <div className="checkout-page">
      <div className="checkout-page__header">
        <button
          type="button"
          className="checkout-page__back-button"
          onClick={onBackToCart}
          aria-label="Back to cart"
        >
          &larr; Back to cart
        </button>
        <h1 className="checkout-page__title">Checkout</h1>
      </div>

      <div className="checkout-page__content">
        <div className="checkout-page__column">
          <AddressForm address={address} errors={errors} onChange={handleFieldChange} />
        </div>

        <div className="checkout-page__column">
          <OrderSummary items={cartItems} />

          <button
            type="button"
            className="checkout-page__pay-button"
            onClick={handlePay}
            disabled={!canPay}
          >
            {isPaying ? 'Processing…' : 'Pay'}
          </button>
        </div>
      </div>
    </div>
  );
}
```

